INSERT OR REPLACE INTO site_content (key, value) VALUES
('profile', '{"name":"Khun Thaw Zin Htun","title":"IT Support Specialist","tagline":"IT support and automation for small businesses.","location":"Yangon, Myanmar","email":"khunthawzinhtun.workspace@gmail.com","github":"","telegram":""}'),
('about', '{"heading":"About","body":"I am an IT support specialist. From 2024 to 2026 I worked as a help desk and service technician at a systems integrator, handling 4,000 tickets across L1, L2, and L3.\n\nMy best work was self-directed. I migrated the company Redmine from version 4 to 6, moving it off CentOS 7 onto a new CentOS 10 server with 4 hours of downtime and zero data loss. I rebuilt the working hour management system into a properly structured app with new features.\n\nNow I work for myself. IT support for small businesses, automation that removes busywork, and AI-assisted builds. I even build portfolio sites like this one."}'),
('skills', '{"categories":[{"name":"IT Support","items":["Help desk L1, L2, L3","Hardware and software troubleshooting","Vendor coordination","Ticketing systems (Redmine)"]},{"name":"Infrastructure","items":["FortiGate firewalls and routers","Cisco switches","Aruba and UniFi wireless","HIKVISION NVR and CCTV","Dell servers","VMware ESXi (6 hosts, 30 VMs)"]},{"name":"Builds and automation","items":["AI-assisted development","Python and PowerShell","Cloudflare (Tunnels, Pages, D1)","Portfolio and business sites"]}]}'),
('projects', '[{"title":"Redmine Migration","description":"Our ticketing system ran Redmine 4 on CentOS 7, which the latest Redmine no longer supports. I set up a new CentOS 10 server, installed Redmine 6, and migrated every ticket and record. 4 hours of downtime, zero data loss.","tech":["Redmine","CentOS","Data migration"],"link":""},{"title":"Working Hours Rebuild","description":"The old working hour system was unstructured and hard to use. I rebuilt it with a proper structure and additional features for the whole staff.","tech":["PHP","Web app"],"link":""},{"title":"Veil Reader","description":"A private Android reader for manga and manhwa. History, bookmarks, and reading progress stay on the phone and nowhere else. Tracker blocking, HTTPS-only browsing, and volume keys turn the pages.","tech":["Android","Kotlin","Privacy"],"link":""},{"title":"Nazarick Bridge","description":"My own server that lets AI assistants run tasks on my Windows machine. A local daemon does the work, a Cloudflare tunnel carries it out, and a health check proves it is alive.","tech":["Python","MCP","Cloudflare Tunnel"],"link":""}]'),
('experience', '[{"role":"IT Help Desk and Service Technician","org":"Systems integrator","period":"2024 - 2026","points":["Handled 4,000 support tickets across L1, L2, and L3 over two years.","Migrated Redmine 4 on CentOS 7 to Redmine 6 on CentOS 10 with 4 hours of downtime and zero data loss.","Rebuilt the working hour management system with proper structure and new features.","Managed FortiGate firewalls and routers, Cisco switches, Aruba and UniFi wireless, HIKVISION CCTV, and 6 ESXi hosts running 30 VMs."]}]'),
('contact', '{"heading":"Contact","text":"I do IT support for small businesses, automation that removes busywork, and portfolio sites like this one. Email is the fastest way to reach me.","email":"khunthawzinhtun.workspace@gmail.com"}');
